(()=>{'use strict';
 const data=window.QUALITY_DATA, model=window.QualityModel;
 const main=document.querySelector('main');
 const text={es:{results:'Resultados',method:'Criterios de cálculo',title:'Calidad de las políticas de igualdad',eyebrow:'GERNIKA-LUMO · EVALUACIÓN 2026',intro:'Dos dimensiones, trece variables y 65 indicadores. Consulta el resultado de cada variable y las evidencias que fundamentan sus indicadores.',global:'Resultado global',provisional:'Provisional',variables:'variables',indicators:'indicadores',weight:'Peso en el global: 50 %',note:'Los indicadores 1.4.3 (presupuesto del plan interno) y 2.1.4 (porcentaje presupuestado para igualdad) mantienen provisionalmente 0 por falta de acreditación. La confirmación de los datos puede modificar el resultado; no equivale a demostrar su inexistencia o un porcentaje inferior al umbral.',see:'Ver indicador',legend:'Estado de los indicadores',SI:'Realizado',PARCIAL:'Parcialmente realizado',NO:'No realizado',pending:'Pendiente',card:'Abrir ficha',back:'Volver a resultados',detail:'Indicadores de la variable',assessment:'Explicación',evidence:'Documentos asociados',original:'Valoración y fuentes originales del Excel',originalLanguage:'Texto original en castellano',source:'Fuente declarada',none:'No hay un archivo documental asignado. Consulta la fuente declarada en el Excel: puede tratarse de entrevistas o referencias externas.',doc:'Documento',points:'puntos',origin:'Identificador original conservado; agrupado en Empleo público conforme a Emakunde.',analysis:'Análisis del expediente',employment:'Ver análisis de empleo público',contracts:'Ver análisis de contratación',grants:'Ver análisis de subvenciones',next:'Siguiente variable',previous:'Variable anterior',local:'Red Kuorum · Gernika-Lumo',date:'Valoración institucional · actualización presupuestaria de octubre de 2026',notfound:'No se ha encontrado esa ficha.',file:'Consultar Excel',pdf:'Consultar documento de Emakunde',analysisIntro:'Detalle de la hoja «Verificación de mandatos» del Excel. Las filas explican el análisis documental; no son nuevos indicadores y no se añaden al cálculo.',sourceSheet:'Excel:',criteria:'Comprobación documental',justification:'Fundamento del análisis',related:'Indicadores relacionados',attachments:'Documentación del expediente',analysisLanguage:'El análisis se reproduce en el castellano original del Excel, conservando sus valoraciones.',viewOriginal:'Abrir documento',coverage:'valorados',change:'Hay indicadores con valoración provisional.'},eu:{results:'Emaitzak',method:'Kalkulu-irizpideak',title:'Berdintasun-politiken kalitatea',eyebrow:'GERNIKA-LUMO · 2026KO EBALUAZIOA',intro:'Bi dimentsio, hamahiru aldagai eta 65 adierazle. Kontsultatu aldagai bakoitzaren emaitza eta adierazleen oinarri diren ebidentziak.',global:'Emaitza globala',provisional:'Behin-behinekoa',variables:'aldagai',indicators:'adierazle',weight:'Emaitza globalean duen pisua: % 50',note:'1.4.3 adierazleak (barne-planaren aurrekontua) eta 2.1.4 adierazleak (berdintasunerako aurrekontu-ehunekoa) 0 puntu dute behin-behinean, egiaztatu gabe daudelako. Datuak baieztatzeak emaitza alda dezake; horrek ez du esan nahi aurrekonturik ez dagoenik edo ehunekoa atalasearen azpitik dagoenik.',see:'Ikusi adierazlea',legend:'Adierazleen egoera',SI:'Eginda',PARCIAL:'Partzialki eginda',NO:'Egin gabe',pending:'Zain',card:'Ireki fitxa',back:'Itzuli emaitzetara',detail:'Aldagaiaren adierazleak',assessment:'Azalpena',evidence:'Lotutako dokumentuak',original:'Excelaren jatorrizko balorazioa eta iturriak',originalLanguage:'Jatorrizko testua gaztelaniaz',source:'Adierazitako iturria',none:'Ez dago esleitutako dokumentu-fitxategirik. Kontsultatu Excelan adierazitako iturria: elkarrizketak edo kanpoko erreferentziak izan daitezke.',doc:'Dokumentua',points:'puntu',origin:'Jatorrizko identifikatzailea mantendu da; Enplegu publikoan multzokatuta, Emakunderen arabera.',analysis:'Espedientearen analisia',employment:'Ikusi enplegu publikoaren analisia',contracts:'Ikusi kontratazioaren analisia',grants:'Ikusi dirulaguntzen analisia',next:'Hurrengo aldagaia',previous:'Aurreko aldagaia',local:'Red Kuorum · Gernika-Lumo',date:'Erakundearen balorazioa · aurrekontu-datuak 2026ko urrian eguneratuta',notfound:'Ez da fitxa hori aurkitu.',file:'Kontsultatu Excela',pdf:'Kontsultatu Emakunderen dokumentua',analysisIntro:'Excelaren «Verificación de mandatos» orriaren xehetasuna. Lerroek dokumentuen analisia azaltzen dute; ez dira adierazle berriak eta ez dira kalkuluan gehitzen.',sourceSheet:'Excel:',criteria:'Dokumentuen egiaztapena',justification:'Analisiaren oinarria',related:'Lotutako adierazleak',attachments:'Espedientearen dokumentazioa',analysisLanguage:'Analisia Excelaren jatorrizko gaztelaniaz erreproduzitzen da, balorazioak mantenduz.',viewOriginal:'Ireki dokumentua',coverage:'baloratuta',change:'Zenbait adierazleren balorazioa behin-behinekoa da.'}};
 let lang='es';try{const x=localStorage.getItem('gernika-quality-language');if(text[x])lang=x;}catch{}
 const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const t=k=>text[lang][k]??k;
 const pct=x=>{if(x===null)return t('pending');const number=new Intl.NumberFormat(lang==='eu'?'eu-ES':'es-ES',{minimumFractionDigits:2,maximumFractionDigits:2}).format(x*100);return lang==='eu'?'%\u00a0'+number:number+'\u00a0%';};
 const getVariable=i=>data.indicators.find(x=>x.id===i)?.variable;
 const badge=()=>`<span class="provisional">${t('provisional')}</span>`;
 const state=i=>`<span class="state" data-state="${e(i.state)}">${e(t(i.state))}</span>`;
 const metricBar=v=>v===null?'':`<div class="bar" aria-hidden="true"><span style="width:${v*100}%"></span></div>`;
 function legend(){return `<div class="legend"><span>${t('legend')}:</span>${['SI','PARCIAL','NO'].map(s=>`<span><i class="swatch" data-state="${s}"></i>${t(s)}</span>`).join('')}</div>`;}
 function strip(items){return `<div class="indicator-strip" aria-label="${t('legend')}">${items.map(i=>`<a data-state="${i.state}" href="#variable/${i.variable}/${i.id}" title="${e(i.id+' · '+t(i.state)+(i.provisional?' · '+t('provisional'):''))}" aria-label="${e(i.id+' · '+t(i.state))}">${i.provisional?'*':''}</a>`).join('')}</div>`;}
 function docLink(id){const d=data.documents.find(x=>x.id===id);return d?`<a href="${d.url}" target="_blank" rel="noopener">${t('doc')} ${e(id)} · ${e(d.title.replace(/^\d+[A-Z]?\.\s*/,''))}</a>`:'';}
 function analysisLinks(v){return v==='2.4'?`<a class="analysis-link" href="#expediente/empleo">${t('employment')} ↗</a>`:v==='2.6'?`<a class="analysis-link" href="#expediente/contratacion">${t('contracts')} ↗</a><a class="analysis-link" href="#expediente/subvenciones">${t('grants')} ↗</a>`:'';}
 function renderOldSummary(){
  const result=model.calculate(data);
  return `<div class="eyebrow">${t('eyebrow')}</div><h1>${t('title')}</h1><p class="intro">${t('intro')}</p><section class="dashboard" aria-label="${t('results')}"><div class="global"><div><h2>${t('global')}</h2><div class="big" id="global-result">${pct(result.global)}</div></div><div>${result.provisional?badge():''}<p class="meta muted">${lang==='es'?'Media de las dos dimensiones':'Bi dimentsioen batezbestekoa'}</p></div></div>${result.dimensions.map(d=>`<div class="dimension-result"><h2>${e(d.title[lang])}</h2><div class="score">${pct(d.value)}</div>${metricBar(d.value)}<p class="meta">${d.variableCount} ${t('variables')} · ${d.count} ${t('indicators')}</p><p class="meta">${t('weight')}</p>${d.provisional?`<div>${badge()}</div>`:''}</div>`).join('')}</section><div class="notice">${t('note')} <a href="#variable/1.4/1.4.3">${t('see')} 1.4.3</a></div>${legend()}${result.dimensions.map(d=>`<section aria-labelledby="dimension-${d.id}"><div class="section-heading"><h2 id="dimension-${d.id}">${d.id}. ${e(d.title[lang])}</h2><span class="meta">${d.variableCount} ${t('variables')}</span></div><div class="variable-grid">${result.variables.filter(v=>v.dimension===d.id).map(v=>{const items=data.indicators.filter(i=>i.variable===v.id);return `<article class="variable-card"><a href="#variable/${v.id}" class="card-main"><div class="card-top"><span class="code">${v.id}</span><strong>${pct(v.value)}</strong></div><h3>${e(v.title[lang])}</h3></a>${strip(items)}<div class="card-bottom"><span class="meta">${v.count} ${t('indicators')}</span>${v.provisional?badge():`<a href="#variable/${v.id}">${t('card')} ↗</a>`}</div>${analysisLinks(v.id)}</article>`;}).join('')}</div></section>`).join('')}`;
 }
 function renderIndicator(i,open){return `<details class="indicator" data-state="${i.state}" id="indicator-${i.id}" ${open?'open':''}><summary><div class="title-line"><span class="code">${i.id}${lang==='eu'?` · ${t('originalLanguage')}`:''}</span><span class="indicator-name" lang="es">${e(i.title)}</span></div><div class="state-wrap">${state(i)}${i.provisional?badge():''}<span class="meta">${Number.isFinite(i.score)?pct(i.score)+' '+dual('media de planes','planen batezbestekoa'):new Intl.NumberFormat(lang==='eu'?'eu-ES':'es-ES').format(model.scores[i.state])+' '+t('points')}</span></div></summary><div class="detail-body">${i.id==='2.3.3'?`<p class="notice">${t('origin')}</p>`:''}<h3>${t('assessment')}</h3><p class="assessment" lang="es">${e(i.assessment)}</p>${i.provisional?`<p class="notice">${t('note')}</p>`:''}${['2.4','2.6'].includes(i.variable)?`<div class="source-links">${analysisLinks(i.variable)}</div>`:''}<h3>${t('source')}</h3><p class="source-declared" lang="es">${e(i.source)}</p><h3>${t('evidence')} <span class="meta">(${i.evidence.length})</span></h3>${i.evidence.length?i.evidence.map(ev=>{const doc=data.documents.find(d=>d.id===ev.documento);return `<div class="evidence"><div class="evidence-head">${docLink(ev.documento)}<span class="evidence-type">${e(doc?.extension||'')}</span></div><p class="meta" lang="es">${e(ev.localizador)}</p><p class="meta" lang="es">${e(ev.alcance)}</p></div>`;}).join(''):`<p class="empty-evidence">${t('none')}</p>`}<details class="original"><summary>${t('original')} (${t('originalLanguage')})</summary><h3>${t('assessment')}</h3><p lang="es">${e(i.assessment)}</p><h3>${t('source')}</h3><p lang="es">${e(i.source)}</p></details></div></details>`;}
 function renderVariable(id,indicator){const result=model.calculate(data),v=result.variables.find(v=>v.id===id);if(!v)return notFound();const items=data.indicators.filter(i=>i.variable===id),d=result.dimensions.find(d=>d.id===v.dimension),idx=result.variables.findIndex(v=>v.id===id);return `<a class="back" href="#resumen">← ${t('back')}</a><div class="detail-header"><div><div class="eyebrow">${e(d.title[lang])} · ${id}</div><h1>${e(v.title[lang])}</h1><div class="stats">${['SI','PARCIAL','NO'].map(s=>`<span class="stat">${v.counts[s]} ${t(s)}</span>`).join('')}</div></div><div class="detail-score"><strong>${pct(v.value)}</strong><span class="meta">${v.valued}/${v.count} ${t('coverage')}</span>${v.provisional?badge():''}</div></div>${v.provisional?`<p class="notice">${t('change')} ${t('note')}</p>`:''}<div class="source-links">${analysisLinks(id)}</div>${id==='2.7'?renderPlanReview():''}<h2 class="section-heading">${t('detail')}</h2>${legend()}<div class="indicator-list">${items.map(i=>renderIndicator(i,i.id===indicator)).join('')}</div><div class="pager">${idx>0?`<a href="#variable/${result.variables[idx-1].id}">← ${t('previous')} · ${result.variables[idx-1].id}</a>`:'<span></span>'}${idx<result.variables.length-1?`<a href="#variable/${result.variables[idx+1].id}">${t('next')} · ${result.variables[idx+1].id} →</a>`:''}</div>`;}
 function renderAnalysis(id){const a=data.analyses.find(a=>a.id===id);if(!a)return notFound();const variable=id==='empleo'?'2.4':'2.6';return `<a class="back" href="#variable/${variable}">← ${e(data.variables.find(v=>v.id===variable).title[lang])}</a><div class="eyebrow">${t('analysis')}</div><h1>${e(a.title[lang])}</h1><p class="intro">${t('analysisIntro')}</p><p class="meta">${t('sourceSheet')} ${a.sourceRows}</p>${a.note?`<p class="notice" lang="es">${e(a.note)}</p>`:''}${renderProvenance()}<p class="notice">${t('analysisLanguage')}</p><div class="expedient-docs"><h2>${t('attachments')}</h2>${a.documents.map(id=>`<p>${docLink(id)}</p>`).join('')}</div><section class="mandates" aria-label="${t('criteria')}">${a.rows.map((row,n)=>`<article class="mandate"><div class="code">${n+1}. ${t('criteria')}</div><h2 lang="es">${e(row.criterion)}</h2><p class="meta" lang="es">${e(row.reference)}</p><div class="mandate-values">${row.values.map((val,k)=>`<div><span lang="es">${e(a.columns[k])}</span><strong class="state" data-state="${val==='SI'||val==='NO'||val==='PARCIAL'?val:'PENDIENTE'}">${e(val)}</strong></div>`).join('')}</div><p class="meta">${t('related')}: ${(row.indicators.match(/\d+\.\d+\.\d+/g)||[]).map(i=>getVariable(i)?`<a href="#variable/${getVariable(i)}/${i}">${i}</a>`:e(i)).join(', ')||e(row.indicators)}</p><details class="original" open><summary>${t('justification')}</summary><p lang="es">${e(row.reason)}</p></details></article>`).join('')}</section>`;}
 function renderMethod(){return `<div class="method"><a class="back" href="#resumen">← ${t('back')}</a><div class="eyebrow">EMAKUNDE · RED KUORUM</div><h1>${t('method')}</h1>${lang==='es'?`<p>El instrumento parte de los estándares de Emakunde y se adapta a Gernika-Lumo. Se conservan trece variables y 65 indicadores.</p><h2>Puntuación de los indicadores</h2><p>Realizado: 1 punto. Parcialmente realizado: 0,5 puntos. No realizado: 0 puntos. El 50 % es el criterio acordado para la categoría parcial; no expresa una medición exacta de la mitad de una actividad.</p><h2>Medias por niveles</h2><ol><li>Cada variable: media de sus indicadores.</li><li>Condiciones estructurales: media de sus seis variables.</li><li>Procedimientos de trabajo: media de sus siete variables.</li><li>Resultado global: media de las dos dimensiones.</li></ol><div class="weights"><div><strong>50 %</strong>Condiciones estructurales</div><div><strong>50 %</strong>Procedimientos de trabajo</div></div><p>Los indicadores pesan igual dentro de su variable; las variables pesan igual dentro de su dimensión. Las trece variables no tienen todas el mismo peso global. Se conserva la precisión del cálculo y se redondean solo los porcentajes mostrados.</p><p>Emakunde propone listas de condiciones y porcentajes. La puntuación parcial y las medias por niveles son criterios acordados para esta aplicación; no constituyen una fórmula global oficial de Emakunde.</p><h2>Tres condiciones excluidas</h2><p>Se excluyen, por la adaptación institucional confirmada para Gernika-Lumo, tres condiciones dirigidas a administraciones de mayor tamaño: unidades especializadas departamentales; coordinación interna departamental para Gobierno Vasco, diputaciones y capitales; y coordinación interinstitucional de igualdad en Gobierno Vasco y diputaciones. Son tres indicadores excluidos, no tres variables eliminadas.</p><h2>Agrupación e identificadores</h2><p>El indicador 2.3.3, sobre méritos de igualdad en selección, está incluido en Empleo público. Su identificador de origen se conserva para mantener la trazabilidad. Formación contiene dos indicadores y Empleo público cinco.</p><h2>Presupuesto interno provisional</h2><p>El indicador 1.4.3 se valora como NO con 0 puntos por decisión provisional de Helena y se incluye entre los siete indicadores del plan interno. Sigue pendiente de confirmación municipal. Por ello, su variable, la dimensión de estructuras y el global se señalan como provisionales.</p><p>Un dato sin información o pendiente de valoración no se convierte automáticamente en cero ni se excluye de una media cerrada. Cualquier nueva exclusión por no aplicabilidad requiere una regla explícita.</p><p>En la revisión de planes sectoriales se aplica la regla expresa acordada el 28/09/2026: «No consta» = no realizado, 0 puntos, incluido en la media.</p><p>En la revisión de planes sectoriales se aplica la regla expresa acordada el 28/09/2026: «No consta» = no realizado, 0 puntos, incluido en la media.</p><h2>Colores y expedientes</h2><p>Cada pieza de color representa un indicador: morado, realizado; naranja, parcial; gris, no realizado. Los colores no clasifican las medias de variables o dimensiones. Los análisis de empleo público, contratación y subvenciones reproducen la hoja de verificación del Excel: sus filas no añaden indicadores al cálculo.</p><h2>Alcance de las evidencias</h2><p>Se conservan las valoraciones del Excel, con las modificaciones del presupuesto interno provisional y del indicador 1.2.9, realizado por la evaluación final del plan, y del indicador 2.1.3, no realizado porque la participación en la comunidad de práctica aún no se ha trasladado al procedimiento presupuestario municipal. Para diálogo social se exige un espacio permanente: el proceso temporal de cuidados no se considera esa estructura. Las propuestas de cambiar las valoraciones de participación, pliegos y planes sectoriales fueron descartadas.</p><p>Las fichas distinguen documentos, fuentes declaradas y valoración. Una previsión, una convocatoria y un acta no acreditan lo mismo. Las asociaciones documentales no cambian automáticamente la puntuación.</p><p>La consulta corresponde a una valoración institucional en 2026 e incluye documentos de distintos años. No representa exclusivamente la ejecución de 2021-2024.</p><h2>Idiomas y fuentes</h2><p>La interfaz y los resúmenes de valoración están disponibles en castellano y euskera. Los enunciados literales, las valoraciones completas, las referencias y los análisis del Excel se conservan en su castellano original para mantener la trazabilidad. Los resúmenes en euskera son traducciones de trabajo.</p>`:`<p>Tresnak Emakunderen estandarrak ditu oinarri, Gernika-Lumora egokituta. Hamahiru aldagai eta 65 adierazle mantentzen dira.</p><h2>Adierazleen puntuazioa</h2><p>Eginda: puntu 1. Partzialki eginda: 0,5 puntu. Egin gabe: 0 puntu. % 50 kategoria partzialerako adostutako irizpidea da; ez da jarduera baten erdiaren neurketa zehatza.</p><h2>Mailakako batezbestekoak</h2><ol><li>Aldagai bakoitza: bere adierazleen batezbestekoa.</li><li>Egiturazko baldintzak: sei aldagaien batezbestekoa.</li><li>Lan-prozedurak: zazpi aldagaien batezbestekoa.</li><li>Emaitza globala: bi dimentsioen batezbestekoa.</li></ol><div class="weights"><div><strong>% 50</strong>Egiturazko baldintzak</div><div><strong>% 50</strong>Lan-prozedurak</div></div><p>Adierazleek pisu bera dute beren aldagaiaren barruan; aldagaiek pisu bera dute beren dimentsioan. Hamahiru aldagaiek ez dute pisu global bera. Kalkuluaren zehaztasuna mantentzen da, eta bistaratutako ehunekoak soilik biribiltzen dira.</p><p>Emakundek baldintzen zerrendak eta ehunekoak proposatzen ditu. Puntuazio partziala eta mailakako batezbestekoak aplikazio honetarako adostutako irizpideak dira, ez Emakunderen formula global ofiziala.</p><h2>Baztertutako hiru baldintzak</h2><p>Gernika-Lumorako baieztatutako egokitzapenagatik, administrazio handiagoei zuzendutako hiru baldintza baztertu dira: sailetako unitate espezializatuak; Eusko Jaurlaritzako, aldundietako eta hiriburuetako sailen barne-koordinazioa; eta Eusko Jaurlaritzako eta aldundietako berdintasuneko erakundearteko koordinazioa. Hiru adierazle baztertu dira, ez hiru aldagai.</p><h2>Multzokatzea eta identifikatzaileak</h2><p>Hautaketan berdintasun-merezimenduei buruzko 2.3.3 adierazlea Enplegu publikoan dago. Jatorrizko identifikatzailea mantentzen da trazabilitaterako. Prestakuntzak bi adierazle ditu eta Enplegu publikoak bost.</p><h2>Barne-aurrekontua, behin-behinean</h2><p>1.4.3 adierazlea EZ eta 0 punturekin baloratu da Helenaren behin-behineko erabakiz, eta barne-planaren zazpi adierazleen artean zenbatzen da. Udalaren baieztapenaren zain dago. Horregatik, aldagaia, egituren dimentsioa eta emaitza globala behin-behinekoak dira.</p><p>Informaziorik gabeko edo baloratzeko zain dagoen datu bat ez da automatikoki zero bihurtzen, eta ez da batezbesteko itxi batetik baztertzen. Aplikagarritasunik ezagatik beste edozein bazterketak irizpide esplizitua behar du.</p><p>Sektoreko planen berrikuspenean, 2026/09/28an adostutako araua aplikatzen da: jasota ez dagoena = egin gabe, 0 puntu, batezbestekoan sartuta.</p><p>Sektoreko planen berrikuspenean, 2026/09/28an adostutako araua aplikatzen da: jasota ez dagoena = egin gabe, 0 puntu, batezbestekoan sartuta.</p><h2>Koloreak eta espedienteak</h2><p>Koloreko pieza bakoitza adierazle bat da: morea, eginda; laranja, partzialki; grisa, egin gabe. Koloreek ez dituzte aldagai edo dimentsioen batezbestekoak sailkatzen. Enplegu publikoaren, kontratazioaren eta dirulaguntzen analisiek Excelaren egiaztapen-orria erreproduzitzen dute; haien lerroak ez dira adierazle berriak.</p><h2>Ebidentzien irismena</h2><p>Excelaren balorazioak mantentzen dira; aldaketak barne-aurrekontuaren behin-behineko balorazioa eta 1.2.9 adierazlea dira; azken hori egindakotzat jotzen da planaren azken ebaluazioagatik. 2.1.3 adierazlea egin gabetzat jo da, praktika-komunitateko parte-hartzea udalaren aurrekontu-prozedurara eraman ez delako. Gizarte-elkarrizketarako gune iraunkorra eskatzen da; aldi baterako zaintza-prozesua ez da egitura horitzat hartzen. Parte-hartzearen eta pleguen aurreko proposamenak baztertu ziren. Planen aldagaia sei planen dokumentu-matrizearekin berriz kalkulatu da: jasota ez dagoena = 0, 2026/09/28an adostuta.</p><p>Fitxek dokumentuak, adierazitako iturriak eta balorazioa bereizten dituzte. Aurreikuspen batek, deialdi batek eta akta batek ez dute gauza bera egiaztatzen. Dokumentuak lotzeak ez du puntuazioa automatikoki aldatzen.</p><p>Kontsultak 2026ko erakunde-balorazioa jasotzen du, urte desberdinetako dokumentuekin. Ez du 2021-2024 aldiko gauzatzea soilik adierazten.</p><h2>Hizkuntzak eta iturriak</h2><p>Interfazea eta balorazio-laburpenak gaztelaniaz eta euskaraz daude. Excelaren hitzez hitzeko enuntziatuak, balorazio osoak, erreferentziak eta analisiak jatorrizko gaztelaniaz mantentzen dira, trazabilitatea gordetzeko. Euskarazko laburpenak laneko itzulpenak dira.</p>`}<div class="source-links"><a href="${data.sources.workbook}">${t('file')}</a><a href="#emakunde/1">${t('pdf')}</a></div></div>`;}
 function notFound(){return `<div class="error"><h1>${t('notfound')}</h1><p><a href="#resumen">${t('back')}</a></p></div>`;}

 const dual=(es,eu)=>lang==='es'?es:eu;
 const navItems=[['inicio','Introducción','Sarrera'],['resumen','Resultados generales','Emaitza orokorrak'],['variables','Fichas de variables','Aldagaien fitxak'],['analisis','Análisis de expedientes','Espedienteen analisia'],['documentacion','Documentación de referencia','Erreferentziazko dokumentazioa'],['metodologia','Criterios de cálculo','Kalkulu-irizpideak']];
 function introIcon(type){const shapes={building:'<path d="M4 10h24L16 3 4 10Zm2 18h20M8 13v11m8-11v11m8-11v11"/>',process:'<rect x="3" y="4" width="10" height="8" rx="2"/><rect x="19" y="20" width="10" height="8" rx="2"/><path d="M13 8h11v8m-4-4 4 4 4-4M19 24H8v-8m-4 4 4-4 4 4"/>',file:'<path d="M8 3h12l6 6v20H8V3Zm12 0v7h6M12 16h10m-10 5h10"/>'};return `<svg viewBox="0 0 32 32" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${shapes[type]||shapes.file}</svg>`;}

 function renderProvenance(){return `<details class="intro-source"><summary>${dual('¿De dónde salen los datos y qué documentos se han revisado?','Nondik datoz datuak eta zer dokumentu aztertu dira?')}<span>＋</span></summary><div class="source-body"><p>${dual('La evaluación se basa en entrevistas y sesiones de trabajo con la técnica de igualdad, Jone Gurrea, y en la revisión documental. La matriz recoge sesiones de 3 y 17 de julio de 2026 y, para determinados indicadores, entrevistas con otras áreas municipales. Cada ficha distingue las fuentes declaradas y las evidencias documentales asociadas.','Ebaluazioa Jone Gurrea berdintasun-teknikariarekin egindako elkarrizketa eta lan-saioetan eta dokumentuen azterketan oinarritzen da. Matrizeak 2026ko uztailaren 3ko eta 17ko saioak eta, adierazle batzuetarako, beste udal-arloetako elkarrizketak jasotzen ditu. Fitxa bakoitzak adierazitako iturriak eta dokumentu-ebidentziak bereizten ditu.')}</p><p>${dual('La revisión se complementó con información publicada en webs institucionales y boletines para empleo público, contratos, subvenciones y planes. Una previsión escrita no acredita por sí sola su ejecución.','Azterketa erakundeen webgune eta aldizkarietan argitaratutako informazioarekin osatu zen, enplegu publikoari, kontratuei, dirulaguntzei eta planei dagokienez. Idatzizko aurreikuspen batek ez du berez gauzatzea egiaztatzen.')}</p><h3>${dual('Acceso al empleo público','Enplegu publikoan sartzea')}</h3><p>${dual('El análisis previo identifica el proceso de estabilización de 2022: bases generales, trece bases específicas y sus correcciones de 2023. Los cuatro documentos enlazados pertenecen a ese proceso. La afirmación de cobertura completa se limita al periodo y al apartado municipal consultados en aquel análisis; esta revisión no verifica de nuevo un censo de todos los procesos publicados.','Aurreko analisiak 2022ko egonkortze-prozesua identifikatzen du: oinarri orokorrak, hamahiru oinarri espezifiko eta 2023ko zuzenketak. Lotutako lau dokumentuak prozesu horretakoak dira. Estaldura osoaren baieztapena orduan aztertutako aldira eta udal-atalera mugatzen da; berrikuspen honek ez du argitaratutako prozesu guztien errolda berriz egiaztatzen.')}</p><h3>${dual('Contratos y subvenciones: cinco documentos en cada muestra','Kontratuak eta dirulaguntzak: bost dokumentu lagin bakoitzean')}</h3><p>${dual('Contratos: paneles expositores de cultura (2022), asfaltado (2024), impresoras (2024), transporte urbano (2025) y bar-cafetería de San Juan Ibarra (2026). Subvenciones: aprendizaje del euskera (2021), deporte (2022), cooperación y cohesión social (ejercicio 2023, publicación 2024), y cultura (2024).','Kontratuak: kulturako erakusketa-panelak (2022), asfaltatzea (2024), inprimagailuak (2024), hiri-garraioa (2025) eta San Juan Ibarrako taberna-kafetegia (2026). Dirulaguntzak: euskara ikastea (2021), kirola (2022), lankidetza, gizarte-kohesioa eta kultura (2024).')}</p><p>${dual('La muestra permite comparar ámbitos y fechas diferentes. El análisis distingue documentos anteriores y posteriores a la reforma normativa de 2022. No se ha localizado una regla previa que explique la selección exacta ni está acreditada su representatividad estadística. El contrato de 2026 pertenece a un contraste posterior al periodo 2021–2024 del IV Plan.','Laginak arlo eta data desberdinak alderatzeko aukera ematen du. Analisiak 2022ko arau-erreformaren aurreko eta ondorengo dokumentuak bereizten ditu. Ez da aurkitu hautaketa zehatza azaltzen duen aurretiko araurik, eta ez dago egiaztatuta ordezkagarritasun estatistikoa. 2026ko kontratua IV. Planaren 2021–2024 aldiaren ondorengo kontrastekoa da.')}</p>${renderPlanReview()}</div></details>`;}
 function renderPlanReview(){const p=data.planReview;if(!p)return '';return `<section class="method"><h2>${dual('Planes sectoriales: evidencias y cálculo','Sektoreko planak: ebidentziak eta kalkulua')}</h2><p>${dual('Se evalúan seis planes con los mismos seis criterios. Realizado = 1; parcial = 0,5; no realizado o «No consta» = 0. El resultado de cada plan es la media de sus seis evaluaciones. El resultado de la variable 2.7 es la media de los seis planes. Para cada indicador se calcula también la media de ese criterio entre los seis planes: ambas vías dan el mismo resultado. No se excluyen los casos sin constancia documental.','Sei plan ebaluatzen dira, sei irizpide berdinekin. Eginda = 1; partzialki = 0,5; egin gabe edo jasota ez dagoena = 0. Plan bakoitzaren emaitza bere sei ebaluazioen batezbestekoa da. 2.7 aldagaiaren emaitza sei planen batezbestekoa da. Adierazle bakoitzerako ere sei planen batezbestekoa kalkulatzen da. Dokumentu-frogarik gabeko kasuak ez dira baztertzen.')}</p><p>${dual('Es un criterio de puntuación acordado para esta evaluación. La ausencia de constancia cuenta como no realizado porque el requisito debería estar documentado. Las evidencias parciales reciben 0,5: en Cultura, la referencia a igualdad de género en los objetivos de Agenda 2030 y las menciones a igualdad en las actuaciones. El cumplimiento completo recibe 1.','Ebaluazio honetarako adostutako puntuazio-irizpidea da. Jasota ez dagoena egin gabekotzat zenbatzen da, betekizunak dokumentatuta egon beharko lukeelako. Ebidentzia partzialek 0,5 puntu jasotzen dute: Kulturan, Agenda 2030eko helburuetako genero-berdintasunak eta jardueretako berdintasun-aipamenek. Betetze osoak puntu 1 jasotzen du.')}</p><p>${dual('Documentación: Antifraude; cinco archivos del PIMACC; Accesibilidad y su anuncio de aprobación; Cultura, con la sinopsis de 19 páginas y el documento en euskera de 71 páginas. Para Turismo 2022–2025 y Euskera 2024–2027 se han localizado referencias oficiales, sin recuperar el texto completo. Se retira la afirmación de que faltan tomos de Accesibilidad.','Dokumentazioa: Iruzurraren aurkako Plana; PIMACCeko bost fitxategi; Irisgarritasuna eta onarpen-iragarkia; Kultura, 19 orrialdeko sinopsiarekin eta euskarazko 71 orrialdeko dokumentuarekin. 2022–2025 Turismo eta 2024–2027 Euskara planen erreferentzia ofizialak aurkitu dira, testu osoa eskuratu gabe. Irisgarritasunaren liburukiak falta direla dioen baieztapena kendu da.')}</p>${p.plans.map(x=>`<details class="intro-source"><summary>${e(x.name)} — ${pct(x.score)}</summary><div class="source-body">${x.criteria.map(c=>`<article class="mandate" lang="es"><h3>${e(c.id)} · ${e(c.title)} · ${c.score} puntos</h3><p>${e(c.finding)}</p><p>${e(c.conclusion)}</p><p class="meta">${e(c.reference)}</p></article>`).join('')}</div></details>`).join('')}<p><strong>${dual('Media de los seis planes','Sei planen batezbestekoa')}: ${pct(p.plans.reduce((a,x)=>a+x.score,0)/p.plans.length)}</strong></p><details class="intro-source"><summary>${dual('Documentos revisados','Aztertutako dokumentuak')}</summary><div class="source-body">${p.documents.map(x=>`<p>${e(x[1])}: ${e(x[2])} (${x[3]} ${dual('páginas','orrialde')}). ${/^(https:|documentos\/)/.test(String(x[4]))?`<a href="${e(x[4])}" target="_blank" rel="noopener">${dual('Consultar fuente','Kontsultatu iturria')}</a>`:e(x[4])}</p>`).join('')}</div></details></section>`;}
 function renderIntro(){const r=model.calculate(data);return `<section class="visual-welcome"><div><div class="eyebrow">${t('eyebrow')}</div><h1>${t('title')}</h1><p>${dual('¿Qué condiciones necesita el Ayuntamiento para impulsar la igualdad?','Zer baldintza behar ditu Udalak berdintasuna bultzatzeko?')}</p><a class="primary-link" href="#resumen">${dual('Ver los resultados','Ikusi emaitzak')} →</a></div><div class="instrument-orbit" aria-label="${dual('2 dimensiones, 13 variables, 65 indicadores','2 dimentsio, 13 aldagai, 65 adierazle')}"><div class="orbit-ring"></div><div class="orbit-core">${introIcon('building')}<strong>Gernika-Lumo</strong><span>${dual('Igualdad','Berdintasuna')}</span></div><div class="orbit-node node-one"><b>2</b><span>${dual('dimensiones','dimentsio')}</span></div><div class="orbit-node node-two"><b>13</b><span>${dual('variables','aldagai')}</span></div><div class="orbit-node node-three"><b>65</b><span>${dual('indicadores','adierazle')}</span></div></div></section><details class="intro-source"><summary>${dual("¿Qué son los indicadores de calidad de Emakunde?","Zer dira Emakunderen kalitate-adierazleak?")} <span>＋</span></summary><div class="source-body"><p>${dual('Los Estándares de Calidad de las Políticas Públicas de Igualdad son un instrumento de autoevaluación institucional elaborado mediante un proceso de trabajo interinstitucional coordinado por Emakunde. Identifican las condiciones necesarias para mejorar la eficacia y la efectividad de las políticas públicas de igualdad de mujeres y hombres.','Berdintasuneko Politika Publikoen Kalitate Estandarrak erakundeen autoebaluaziorako tresna dira, Emakundek koordinatutako erakundearteko lan-prozesu batean landua. Emakumeen eta gizonen berdintasunerako politika publikoen eraginkortasuna hobetzeko beharrezko baldintzak identifikatzen dituzte.')}</p><p>${dual('El documento propone listas de comprobación para examinar qué condiciones cumple cada institución y en cuáles necesita avanzar. Comprende tanto las estructuras que permiten diseñar y desarrollar las políticas de igualdad como la incorporación de la perspectiva de género en los procedimientos habituales de la administración.','Dokumentuak egiaztapen-zerrendak proposatzen ditu, erakunde bakoitzak zer baldintza betetzen dituen eta zeinetan aurrera egin behar duen aztertzeko. Berdintasun-politikak diseinatzeko eta garatzeko egiturak nahiz administrazioaren ohiko prozeduretan genero-ikuspegia txertatzea hartzen ditu barne.')}</p><p>${dual('Los porcentajes de esta consulta expresan el cumplimiento de esas condiciones institucionales. No equivalen al porcentaje de igualdad alcanzado en el municipio ni miden por sí solos el impacto de las políticas sobre la vida de mujeres y hombres. Permiten identificar fortalezas y aspectos que requieren mejora.','Kontsulta honetako ehunekoek erakunde-baldintza horien betetze-maila adierazten dute. Ez dira udalerrian lortutako berdintasunaren ehunekoa, eta ez dute berez neurtzen politikek emakumeen eta gizonen bizitzan duten eragina. Indarguneak eta hobetu beharreko alderdiak identifikatzeko balio dute.')}</p><a href="#emakunde/1">${dual('Consultar el documento de Emakunde · contexto y metodología','Kontsultatu Emakunderen dokumentua · testuingurua eta metodologia')} →</a></div></details>${renderProvenance()}<section class="instrument-tree"><div class="tree-heading"><span>${dual('EL INSTRUMENTO, DE UN VISTAZO','TRESNA, BEGIRATU BATEAN')}</span><h2>${dual('Dos dimensiones que se complementan','Elkarren osagarri diren bi dimentsio')}</h2><p>${dual('Selecciona una variable para abrir sus indicadores.','Hautatu aldagai bat haren adierazleak irekitzeko.')}</p></div><div class="tree-branches">${r.dimensions.map((d,index)=>`<section class="tree-branch branch-${index}"><div class="branch-head"><div class="branch-icon">${introIcon(index?'process':'building')}</div><div><span>${dual('DIMENSIÓN','DIMENTSIOA')} ${index+1}</span><h3>${e(d.title[lang])}</h3></div></div><div class="branch-leaves">${r.variables.filter(v=>v.dimension===d.id).map(v=>`<a href="#variable/${v.id}"><span class="leaf-id">${v.id}</span><span>${e(v.title[lang])}</span><b aria-hidden="true">↗</b></a>`).join('')}</div></section>`).join('')}</div></section><details class="visual-calculation question-calculation"><summary>${dual('¿Cómo se calculan los resultados?','Nola kalkulatzen dira emaitzak?')}<span>＋</span></summary><div class="question-content"><div class="calculation-flow"><div><span class="flow-pictogram">● ● ●</span><strong>${dual('Indicadores','Adierazleak')}</strong><small>${dual('Realizado · Parcial · No realizado','Eginda · Partzialki · Egin gabe')}</small><b>1 · 0,5 · 0</b></div><span class="flow-arrow" aria-hidden="true">→</span><div><span class="flow-pictogram">▤</span><strong>13 ${dual('variables','aldagai')}</strong><small>${dual('Media de sus indicadores','Adierazleen batezbestekoa')}</small></div><span class="flow-arrow" aria-hidden="true">→</span><div><span class="flow-pictogram">◧ ◧</span><strong>2 ${dual('dimensiones','dimentsio')}</strong><small>${dual('Media de sus variables','Aldagaien batezbestekoa')}</small></div><span class="flow-arrow" aria-hidden="true">→</span><div class="flow-final"><span class="flow-pictogram">◎</span><strong>${dual('Resultado global','Emaitza orokorra')}</strong><small>${dual('Cada dimensión pesa el 50 %','Dimentsio bakoitzak % 50eko pisua')}</small></div></div><p>${dual('Los porcentajes reflejan condiciones institucionales, no el grado de igualdad alcanzado en el municipio.','Ehunekoek erakunde-baldintzak adierazten dituzte, ez udalerrian lortutako berdintasun-maila.')} <a href="#metodologia">${dual('Consultar los criterios acordados','Kontsultatu adostutako irizpideak')} →</a></p></div></details><section class="intro-bottom-links"><a href="#analisis">${introIcon('process')}<span>${dual('Análisis de expedientes','Espedienteen analisia')}<small>${dual('Empleo público · Contratación · Subvenciones','Enplegu publikoa · Kontratazioa · Dirulaguntzak')}</small></span><b>→</b></a><a href="#documentacion">${introIcon('file')}<span>${dual('Documentación de referencia','Erreferentziazko dokumentazioa')}<small>${dual('Consultar las fuentes y las evidencias','Kontsultatu iturriak eta ebidentziak')}</small></span><b>→</b></a></section>`;}

 function renderSummary(){const r=model.calculate(data);return `<div class="eyebrow">${t('eyebrow')}</div><h1>${dual('Resultados generales','Emaitza orokorrak')}</h1><section class="overall"><div><h2>${t('global')}</h2><p>${dual('Media de las dos dimensiones','Bi dimentsioen batezbestekoa')}</p>${r.provisional?badge():''}</div><strong id="global-result">${pct(r.global)}</strong></section><div class="dimension-charts">${r.dimensions.map(d=>`<section class="dimension-chart"><div class="chart-heading"><h2>${e(d.title[lang])}</h2><strong>${pct(d.value)}</strong></div><p class="meta">${t('weight')}${d.provisional?' · '+t('provisional'):''}</p><h3>${dual('Resultado por variable','Emaitza aldagaiaren arabera')}</h3><div class="chart-rows">${r.variables.filter(v=>v.dimension===d.id).map(v=>`<a class="chart-row" href="#variable/${v.id}"><span class="chart-label">${v.id} · ${e(v.title[lang])}</span><span class="chart-track"><span style="width:${v.value===null?0:v.value*100}%"></span></span><strong>${pct(v.value)}</strong></a>`).join('')}</div><a class="section-link" href="#variables/${d.id}">${dual('Ver las fichas de esta dimensión','Ikusi dimentsio honetako fitxak')} →</a></section>`).join('')}</div><p class="notice">${t('note')} <a href="#variable/1.4/1.4.3">${t('see')}</a></p>`;}
 function renderCards(dim){const html=renderOldSummary();const start=html.indexOf('<section aria-labelledby="dimension-');let cards=html.slice(start);if(dim){const boundary=cards.indexOf('<section aria-labelledby="dimension-2');cards=dim==='1'?cards.slice(0,boundary):cards.slice(boundary);}return `<h1>${dual('Fichas de variables','Aldagaien fitxak')}</h1><p class="intro">${dual('Abre una ficha para consultar sus indicadores, las explicaciones completas y las evidencias asociadas.','Ireki fitxa bat adierazleak, azalpen osoak eta lotutako ebidentziak kontsultatzeko.')}</p>${legend()}${cards}`;}
 function renderAnalyses(){return `<h1>${dual('Análisis de expedientes','Espedienteen analisia')}</h1><p class="intro">${t('analysisIntro')}</p><div class="analysis-index">${data.analyses.map(a=>`<a href="#expediente/${a.id}"><h2>${e(a.title[lang])}</h2><p>${dual('Documentos revisados, comprobaciones y explicación de las valoraciones.','Aztertutako dokumentuak, egiaztapenak eta balorazioen azalpena.')}</p><span>${dual('Consultar el análisis','Kontsultatu analisia')} →</span></a>`).join('')}</div>`;}
 function renderDocs(){return `<h1>${dual('Documentación de referencia','Erreferentziazko dokumentazioa')}</h1><p class="intro">${dual('Fuentes del instrumento y documentos asociados a los indicadores. Las fichas especifican qué acredita cada evidencia.','Tresnaren iturriak eta adierazleei lotutako dokumentuak. Fitxek ebidentzia bakoitzak zer egiaztatzen duen zehazten dute.')}</p><div class="source-links"><a href="${data.sources.workbook}">${t('file')}</a><a href="#emakunde/1">${t('pdf')}</a></div><div class="document-index">${data.documents.map(d=>`<article>${docLink(d.id)}<span class="meta">${e(d.extension)}</span></article>`).join('')}</div>`;}


 const emakundePages=[{"image": "data:image/jpeg;base64,", "text": "   \nEstándares de Calidad de las \nPolíticas Públicas de Igualdad  \n \n \n"}, {"image": "data:image/jpeg;base64,", "text": "1 \n \n \nCONTEXTO Y OBJETO \nVistas las últimas evaluaciones (de 2015) realizadas sobre la Ley 4/2005 de 18 de febrero, \npara la I gualdad de Mujeres y H ombres, la Comisión Interinstitucional para la Igualdad  de \nMujeres y Hombres creó un Grupo Técnico de Trabajo.  El objetivo de este grupo es mejorar \nla eficiencia y efectividad de las políticas públicas de igualdad de  mujeres y hombres, \nestableciendo unos estándares de calidad y mejorando la coordinación entre instituciones, \nsobre todo en lo que respecta al ámbito local. En cualquier caso, este informe recoge \núnicamente la parte relativa a  los estándares de calidad, y que la parte relativa a la mejora \nen la coordinación entre las instituciones, se abordará en la segunda etapa del proceso. \n \n \nSOBRE EL PROCESO \nDos documentos han sido el fundamento y punto de partida de este proceso. Por un lado, \nla Ley 4/2005 de 18 de febrero, para la igualdad entre Mujeres y Hombres. Por otro lado, el \ncuestionario sobre gobernanza correspondiente a la evaluación del VI. Plan para la Igualdad \nde Mujeres y Hombres. \nEl equipo de trabajo que ha posibilitado la implantación de los estándares de calidad está \ncompuesto por el personal técnico de igualdad de las siguientes instituciones que forman \nparte de la Comisión Interinstitucional para la Igualdad de Mujeres y Hombres: \n- Emakunde (coordinadora del proceso) \n- Diputación Foral de Álava \n- Diputación Foral de Bizkaia \n- Diputación Foral de Guipúzcoa \n"}, {"image": "data:image/jpeg;base64,", "text": "2 \n \n- EUDEL \n- Ayuntamiento de Galdakao \n \nTambién han participado otras dos instituciones, realizando aportaciones en la fase de \ncontraste: \n- Ayuntamiento de Vitoria-Gasteiz \n- Mancomunidad del Alto Urola \n \n \nEl proceso ha tenido una duración de 6 meses. \nSOBRE EL PUNTO DE VISTA \nA la hora de establecer los estándares de calidad para las políticas públicas de igualdad en la \nCAE, el mayor reto ha sido la definición de lo que se entiende por cali dad dentro de las \npolíticas públicas de igualdad. Esta es la definición y el objeto que se desprende de ella: \n \n \n"}, {"image": "data:image/jpeg;base64,", "text": "3 \n \nPor lo tanto, la propuesta realizada se basa en el siguiente punto de vista : no se trata de \nestablecer mínimos o máximos, sino las condiciones necesarias para que las políticas de \nigualdad tengan el efecto deseado, en la mayor medida posible. \nPRESENTACIÓN DE LOS ESTÁNDARES DE CALIDAD \nEl segundo elemento que debemos dejar claro es cómo se agrupa el contenido de este \ndocumento. Los estándares de calidad se clasifican en dos grandes bloques: \nI. Condiciones estructurales. Condiciones necesarias para el diseño, \nimplementación y desarrollo de unas adecuadas políticas públicas de \nigualdad. \nII. Perspectiva de géne ro en los procedimientos de trabajo. Consiste en \nintegrar la perspectiva de género en las acciones y procedimientos llevados  \na cabo por la administración. \nEs importante entender que las condiciones estructurales son imprescindibles para poder \ndesarrollar correctamente la perspectiva de género en los procedimientos de trabajo. Las \ncondiciones estructurales son las bases y cimientos para la implementación de las políticas \nde igualdad. Por ese motivo, el primer bloque es de gran importancia. \nLos dos bloques tienen una serie de variables: \nCondiciones estructurales \n(6 variables) \nPerspectiva de género en los \nprocedimientos de trabajo \n(7 variables) \nUnidades administrativas específicas para la \nigualdad de  mujeres y hombres \nPlanificación para la igualdad de mujeres y \nhombres \nNormativa específica para la igualdad  \nPlanes internos para la igualdad  \nEstructuras de coordinación en materia de \nigualdad \nÓrganos para el dialogo social1 \nPresupuestos con perspectiva de género \nEstadísticas e investigaciones \nFormación en igualdad \nAcceso, provisión y promoción al empleo \npúblico \nIgualdad  en la normativa \nCláusulas de igualdad en subvenciones y \ncontratos públicos \nPerspectiva de género en planes sectoriales \ny transversales \n \n                                                           \n1 Cuando hablamos sobre órganos para el dialogo social, no nos referimos solamente a sindicatos y empresas. "}, {"image": "data:image/jpeg;base64,", "text": "4 \n \n  \nCONDICIONES BÁSICAS. Esas variables son \nlas bases para el desarrollo de cualquier \npolítica de igualdad. Son como los cimientos \nde una casa. \nCONDICIONES COMPLEMENTARIAS. Son \nvariables totalmente necesarias para el \ndesarrollo de políticas públicas de igualdad, \ny se sustentan en las condiciones básicas. \nSon como el tejado de una casa: necesario, \npero sin cimientos, no hay casa.  \n \nCada una de esas variables tiene un grupo de condiciones, que se presentan a modo de \nchecklist. Junto a las condiciones aparecerá un cuadro, en el cual, cada institución, sea cual \nsea su nivel, podrá marcar aquellas que cumple expresamente. De esta forma, podremos \nver cuáles serán los puntos que mejor se cumplen y en cuáles se debe enfatizar más. \nAl final de cada lista aparece el símbolo de porcentaje ( %). Así ,  se podrá calcular el \nporcentaje que nos permitirá conocer en qué medida se cumplen los estándares de calidad.2 \nAl final del documento, hay una ficha de trabajo en la que aparecen todas las variables y \ndonde se podrá anotar el porcentaje correspondiente a cada una. También hay un campo \npara las sugerencias, para que cada institución pueda dejar constancia de sus reflexiones en \ntorno a la mejora de las políticas de igualdad. \n \n  \n                                                           \n2 Para eso, se utiliza la proporción de las variables existentes. Pongamos que tenemos 5 variables. El 100% son las \n5 variables; 2 de ellas serían el 40%. Del mismo modo, debemos tener en cuenta que no todas las instituciones \ntienen por qué cumplir todas las variables. Por ejemplo, los municipios pequeños no tienen por qué calcular el \nporcentaje con todas las variables, sino con esas variables que deberán desarrollar según sus competencias \nmunicipales. \n"}, {"image": "data:image/jpeg;base64,", "text": "5 \n \n \n \n \n \n¿Qué supone? \nLa existencia de un órgano o unidad administrativa específica para la \nigualdad de mujeres y hombres. \n \nLa existencia de personal técnico que se dedique exclusivamente a la \nigualdad. \n \nLa inclusión en las relaciones de puesto de trabajo (RTP)  la plaza de la \npersona trabajadora técnica de igualdad entre las plazas de l personal \ntécnico superior. \n \nLa inclusión de requisitos de formación específica sobre igualdad en la s \nplazas del personal técnico de igualdad. \n \nLa adscripción del órgano o unidad administrativa para la igualdad a la \nestructura con mayor grado de jerarquía de la institución (presidencia, \nalcaldía o equivalente). \n \nLa existencia de unidades de igualdad -específicas y especializadas - en \nlos departa mentos del Gobierno Vasco, d iputaciones forales y de los \nayuntamientos de las capitales. \n \nLa existencia de un presupuesto para la unidad administrativa u órgano \npara la igualdad dentro de la institución. \n \nNivel de cumplimiento de los estándares de calidad ....% \n  \n \n \n  \nCONDICIONES ESTRUCTURALES \nUNIDADES ADMINISTRATIVAS ESPECÍFICAS PARA LA IGUALDAD DE MUJERES Y \nHOMBRES \n"}, {"image": "data:image/jpeg;base64,", "text": "6 \n \n \n \n \n \n¿Qué supone? \nLa existencia de planes o programas para la igualdad en vigor, según lo \nestablecido en el artículo 15 de la Ley 4/2005. \n \nTener una evaluación del plan anterior y/o un diagnóstico, previo a la \nrealización del plan o programa de igualdad en vigor.  \n \nLa participación política de todas las partes implicadas en la realización \ndel plan o programa de igualdad. \n \nLa participación técnica de todas las partes implicadas en la realización \ndel plan o programa de igualdad. \n \nLa inclusión de procesos y mecanismos para la participación de \ncolectivos feministas y asociaciones en la realización del plan de \nigualdad. \n \nLa existencia de un presupuesto específico para los planes o programas \nde igualdad en vigor. \n \nLa existencia de un calendario establecido para el plan o programa de \nigualdad en vigor. \n \nLa existencia de un sistema de seguimiento del plan o programa de \nigualdad en vigor. \n \nLa existencia de un sistema de evaluación del plan o programa de \nigualdad en vigor. \n \nLa integración de los objetivos, acciones e indicadores básicos  del plan \no programa de igualdad y sus correspondientes indicadores de \nevaluación en el plan estratégico o equivalente de la institución. \n \nNivel de cumplimiento de los estándares de calidad ....% \n \nCONDICIONES ESTRUCTURALES \nPLANIFICACIÓN PARA LA IGUALDAD DE MUJERES Y HOMBRES \n"}, {"image": "data:image/jpeg;base64,", "text": "7 \n \n \n \n  \n \n¿Qué supone? \nLa existencia de una normativa específica  propia en materia de \nigualdad. \n \nNivel de cumplimiento de los estándares de calidad ....% \n \n  \nCONDICIONES ESTRUCTURALES \nNORMATIVA ESPECÍFICA PARA LA IGUALDAD \n"}, {"image": "data:image/jpeg;base64,", "text": "8 \n \n \n \n \n¿Qué supone? \nLa existencia de un plan de igualdad interno en cumplimiento de lo \nestablecido en la disposición adicional séptima del Estatu to Básico del \nEmpleado Público. \n \nTener realizada una evaluación del plan anterior y/o un diagnóstico, \nprevio a la realización del plan interno en vigor. \n \nLa existencia de un presupuesto para el plan de igualdad interno.  \nLa existencia de un calendario establecido para el plan de igualdad \ninterno. \n \nLa existencia de un sistema de seguimiento para el plan de igualdad \ninterno. \n \nEl órgano competente en el ámbito de la función pública, o su \nequivalente, tendrá la responsabilidad del plan de igualdad interno. \n \nLa inclusión de los objetivos s, acciones e indicadores básicos en el \nmodelo de gestión pública avanzada o algún instrumento común \nequivalente, en caso de que lo hubiera. \n \nNivel de cumplimiento de los estándares de calidad ....% \n \n \n \n \n \n \n \n \n \n \nCONDICIONES ESTRUCTURALES \nPLANES INTERNOS PARA LA IGUALDAD \n"}, {"image": "data:image/jpeg;base64,", "text": "9 \n \n \n \n \n \n \n¿Qué supone?  \n \nLa existencia de una estructura política y técnica para la coordinación  \nespecífica de las políticas de igualdad. \n \n \nLa persona que ostenta la presidencia de las estructuras de coordinación \ninterdepartamental de igualdad será la persona de mayor rango \njerárquico de la institución (presidencia, alcaldía o equivalente). \n \nCada departamento3  tendrá una estructura de coordinación interna para \nel seguimiento de la política de igualdad, por lo menos en lo q ue \nrespecta al Gobierno Vasco, diputaciones forales y ayuntamientos de las \ncapitales. \n \nLa existencia de una estructura de coordinación interinstitucional en \nmateria de igualdad, en el Gobierno Vasco y en las diputaciones forales. \n \nLa existencia de una estructura de coordinación interinstitucional en el \námbito de la violencia contra las mujeres. \n \nLa existencia de una estructura de coordinación interdepartamental en \nmateria de violencia contra las mujeres. \n \nLa participación en estructuras de coordinación interinstitucional por \nparte de las unidades administrativas de igualdad, en el  caso del \nGobierno Vasco y las diputaciones f orales, y en el caso de los \nAyuntamientos, siempre que sean designados para ello. \n \nNivel de cumplimiento de los estándares de calidad ....% \n  \n                                                           \n*Una estructura de coordinación es un grupo de trabajo para el desarroll o sistemático de ciertos temas.  A \nmenudo, en el caso de instituciones pequeñas, no se le llama «estructura de coordinación». Sin embargo, en \neste caso, se entenderá como «estructura de coordinación, siempre que se cumplan los requisitos descritos. \n3 A pesar de utilizar la palabra «departamento», nos referimos a cualquier unidad organizativa (áreas, ámbitos o \nequivalentes). \n \nCONDICIONES ESTRUCTURALES \nESTRUCTURAS DE COORDINACIÓN EN MATERIA DE IGUALDAD \n"}, {"image": "data:image/jpeg;base64,", "text": "10 \n \n \n \n \n¿Qué supone? \nLa existencia de espacios par a la participación y el diálogo, al menos, \nentre asociaciones y colectivos feministas, a nivel local, foral y/o \nautonómico. \n \nLa puesta en marcha de procesos dirigidos a garantizar la participación , \nal menos,  de asociaciones y colectivos feministas a nivel local, foral y/o \nautonómico. \n \nNivel de cumplimiento de los estándares de calidad ....% \n \n \n  \nCONDICIONES ESTRUCTURALES \nORGANOS PARA EL DIALOGO SOCIAL \n"}, {"image": "data:image/jpeg;base64,", "text": "11 \n \n \n \n \n¿Qué supone? \nLa existencia de un presupuesto anual dirigido al ámbito de la igualdad \nde mujeres y hombres. \n \nLa e valuación previa del impacto de género del presupuesto \ninstitucional. \n \nEl d esarrollo de los proyectos o programas para el avance de la \ninserción de la perspectiva de género en los presupuestos. \n \nEl a umento del porcentaje dirigido a políticas de igualdad, hasta \nalcanzar al menos el 1% por ciento. \n \nLa a probación de acuerdos, instrucciones o pautas para incluir  la \nperspectiva de género en los presupuestos. \n \nNivel de cumplimiento de los estándares de calidad ....% \n \n  \nPERSPECTIVA DE GÉNERO EN PROCEDIMIENTOS DE TRABAJO \nPRESUPUESTOS CON PERSPECTIVA DE GÉNERO \n"}, {"image": "data:image/jpeg;base64,", "text": "12 \n \n \n \n \n¿Qué supone? \nLa i nserción de la variable del sexo en todas las recogidas de d atos, \nencuestas y estadísticas. \n \nLa diferenciación de sexos de forma sistemática a la hora de interpretar \ny utilizar la información. \n \nEl cruce sistemático de la variable del sexo y otras variables a la hora de \ninterpretar y utilizar la información. \n \nLa i dentificación y análisis de las brechas de género a la hora de \ninterpretar la información. \n \nLa inclusión de indicadores de género que ayuden a conocer mejor las \ndesigualdades entre mujeres y hombres. \n \nNivel de cumplimiento de los estándares de calidad ....% \n \n  \n \nPERSPECTIVA DE GÉNERO EN PROCEDIMIENTOS DE TRABAJO \nESTADÍSTICAS E INVESTIGACIONES \nPERSPECTIVA DE GÉNERO EN PROCEDIMIENTOS DE TRABAJO \nESTADÍSTICAS E INVESTIGACIONES \n"}, {"image": "data:image/jpeg;base64,", "text": "13 \n \n \n \n \n¿Qué supone?  \nLa existencia de un plan de formación en ámbito de igualdad de \nmujeres y hombres. \n \n \nLa inclusión  de la perspectiva de género en  actividades de formación \nque no versen sobre la materia de igualdad de mujeres y hombres. \n \n \nNivel de cumplimiento de los estándares de calidad ....% \n \n  \nPERSPECTIVA DE GÉNERO EN PROCEDIMIENTOS DE TRABAJO \nFORMACIÓN EN IGUALDAD \n"}, {"image": "data:image/jpeg;base64,", "text": "14 \n \n \n \n \n¿Qué supone?  \nLa valoración de formación y méritos en materia de igualdad, en \nprocesos de selección que no tienen una conexión específica con \npuestos de trabajo relacionados con el área de igualdad. \n \nLa inserción de contenidos sobre la igualdad entre mujeres y hombres \nen procesos de acceso , provisión y promoción  al empleo público, \nprovisión y subida de nivel, para cualquier puesto de trabajo. \n \nLa valoración de las desigualdades entre mujeres y hombres e inserción \nde medidas  para corregirlas  en las bases para el acceso , provisión y \npromoción al empleo público. \n \nLa i nserción de cláusulas  sobre una representación equilibrada en la \ncomposición de jurados de acceso , provisión y promoción  al empleo \npúblico. \n \nLa capacidad de garantizar la perspectiva de género en los jurados de \nprocesos selección, por parte de las personas traba jadoras \ncompetentes en función pública. \n \nNivel de cumplimiento de los estándares de calidad ....% \n \n  \nPERSPECTIVA DE GÉNERO EN PROCEDIMIENTOS DE TRABAJO \nACCESO, PROVISIÓN Y PROMOCIÓN AL EMPLEO PÚBLICO \n"}, {"image": "data:image/jpeg;base64,", "text": "15 \n \n \n \n \n¿Qué supone? \nLa aprobación de acuerdos e instrucciones para evaluaciones previas \nsobre impacto de género en la institución. \n \nRealización de evaluaciones sobre el impacto de género de la \nnormativa, de forma sistemática. \n \n \nLa existencia de un sistema de seguimiento de la realización de \nevaluaciones sobre el impacto de género. \n \n \nNivel de cumplimiento de los estándares de calidad ....% \n \n  \nPERSPECTIVA DE GÉNERO EN PROCEDIMIENTOS DE TRABAJO \nIGUALDAD EN LA NORMATIVA \n"}, {"image": "data:image/jpeg;base64,", "text": "16 \n \n \n \n \n¿Qué supone? \n \nLa inclusión de cláusulas sobre igualdad en los contratos, en las \nespecificaciones técnicas, criterios de valoración y condiciones \nadministrativas. \n \n \n \nAprobación de instrucciones y  acuerdos para incorporar la igualdad en \nla contratación pública. \n \n \nLa existencia de un sistema de seguimiento del cumplimiento de las \ncláusulas de igualdad en la contratación pública. \n \n \nLa existencia de un mecanismo sancionador para los casos en los que \nno se cumplan los criterios establecidos en las cláusulas de iguald ad en \nla contratación pública. \n \n \nInserción de cláusulas sobre igualdad en las subvenciones (nominativas, \ndirectas y de concurrencia competitiva). \n \n \n \nAprobación de instrucciones y acuerdos sobre  la inserción de cláusulas \nde igualdad en las subvenciones públicas. \n \n \nLa existencia de un sistema de seguimiento del cumplimiento de las \ncláusulas de igualdad en las subvenciones públicas. \n \n \nLa existencia de un mecanismo sancionador para los casos en los que \nno se cumplan los criterios establecidos en las cláusulas de igualdad en \nlas subvenciones públicas. \n \n \nNivel de cumplimiento de los estándares de calidad ....% \n \nPERSPECTIVA DE GÉNERO EN PROCEDIMIENTOS DE TRABAJO \nCLAUSULAS DE IGUALDAD EN SUBVENCIONES Y CONTRATOS PÚBLICOS \n"}, {"image": "data:image/jpeg;base64,", "text": "17 \n \n  \n \n \n¿Qué supone? \nLa existencia de planes estratégicos y transversales que cuenten con \ndiagnósticos previos que analicen la desigualdad entre mujeres y \nhombres en el ámbito de actuación correspondiente. \n \n \nLa inclusión de objetivos de igualdad de mujeres y hombres en planes y \nprogramas estratégicos sectoriales y transversales, siguiendo al \ndiagnóstico realizado. \n \n \n \nLa i nclusión de acciones de igualdad en programas y planes \nestratégicos transversales y sectoriales. \n \n \n \nLa i nclusión de variables por sexo e indicadores de género en los \nsistemas de seguimiento y evaluación de planes transversales y \nsectoriales. \n \n \n \nLa participación de especialistas y unidades administrativas de igualdad \nen el diseño de planes transversales y sectoriales. \n \n \n \nLa participación de especialistas y unidades administrativas de igualdad \nen el seguimiento y evaluación de planes transversales y sectoriales. \n \n \nNivel de cumplimiento de los estándares de calidad ....% \n \n  \nPERSPECTIVA DE GÉNERO EN PROCEDIMIENTOS DE TRABAJO \nPERSPECTIVA DE GÉNERO EN PLANES SECTORIALES Y TRANSVERSALES \n"}, {"image": "data:image/jpeg;base64,", "text": "18 \n \n \n \n  \n \nFICHA DE LAS CONDICIONES ESTRUCTURALES \n¿En qué medida estamos cumpliendo los estándares de calidad? \n \n \nPlanes para la igualdad de mujeres y \nhombres \n                 %        \n¿Qué podemos hacer para mejorarlos? \n \nPlanes de igualdad internos \n                 %        \n¿Qué podemos hacer para mejorarlos? \n \nUnidades administrativas específicas para \nla igualdad entre mujeres y hombres \n                % \n¿Qué podemos hacer para mejorarlas? \n \nÓrganos para el dialogo social \n                 %        \n¿Qué podemos hacer para mejorarlos? \n \nEstructuras de coordinación en materia \nde igualdad \n                  %        \n¿Qué podemos hacer para mejorarlos? \n \n \nNormativa específica para la igualdad    \n                \n% \n \n¿Qué podemos hacer para mejorarlas? \n "}, {"image": "data:image/jpeg;base64,", "text": "19 \n \n \n \n \n \n \n \n \n \n \n  \n \nPERSPECTIVA DE GÉNERO EN PROCEDIMIENTOS DE TRABAJO. FICHA \n¿En qué medida estamos cumpliendo los estándares de calidad? \n \nPresupuestos con perspectiva de \ngénero \n                %           \n¿Qué podemos hacer para mejorarlos? \n \nEstadísticas y investigaciones \n%        \n¿Qué podemos hacer para mejorarlos? \n \nFormación en igualdad \n%        \n¿Qué podemos hacer para mejorarla? \n \nAcceso, provisión y promoción al \nempleo público \n               %        \n¿Qué podemos hacer para mejorarlo? \n \nIgualdad en la normativa \n%        \n¿Qué podemos hacer para mejorarla? \n \nCláusulas de igualdad en \nsubvenciones y contratos públicos \n%        \n¿Qué podemos hacer para mejorarlas? \n "}, {"image": "data:image/jpeg;base64,", "text": "20 \n \n \n \n \n \n \n \n \n \n  \n \n \n \n \n \n \n \n          \n \n \n \nPERSPECTIVA DE GÉNERO EN PROCEDIMIENTOS DE TRABAJO. FICHA \n¿En qué medida estamos cumpliendo los estándares de calidad? \nPerspectiva de género en planes \nsectoriales y transversales \n%        \n¿Qué podemos hacer para mejorarla? \n "}];

 function renderEmakunde(raw,zoom){const page=Math.min(21,Math.max(1,Number.parseInt(raw)||1)),item=emakundePages[page-1];return `<a class="back" href="#inicio">← ${dual('Volver a la introducción','Itzuli sarrerara')}</a><h1>${dual('Estándares de calidad de Emakunde','Emakunderen kalitate-estandarrak')}</h1><p>${dual('Documento original completo. Puedes recorrer sus 21 páginas sin salir de la aplicación.','Jatorrizko dokumentu osoa. Bere 21 orrialdeak aplikaziotik irten gabe kontsulta ditzakezu.')}</p><div class="pdf-controls">${page>1?`<a href="#emakunde/${page-1}">← ${dual('Anterior','Aurrekoa')}</a>`:'<span></span>'}<label>${dual('Página','Orrialdea')} <select id="pdf-page">${emakundePages.map((_,n)=>`<option value="${n+1}" ${n+1===page?'selected':''}>${n+1} / 21</option>`).join('')}</select></label>${page<21?`<a href="#emakunde/${page+1}">${dual('Siguiente','Hurrengoa')} →</a>`:'<span></span>'}<a href="#emakunde/${page}/${zoom==='ampliar'?'normal':'ampliar'}">${zoom==='ampliar'?dual('Ajustar al ancho','Egokitu zabalerara'):dual('Ampliar','Handitu')}</a></div><div class="pdf-page-scroll"><img class="pdf-page ${zoom==='ampliar'?'zoomed':''}" src="${item.image}" alt="${dual('Página','Orrialdea')} ${page} · ${dual('Estándares de calidad de Emakunde','Emakunderen kalitate-estandarrak')}"></div><details class="pdf-text"><summary>${dual('Consultar el texto de esta página','Kontsultatu orrialde honetako testua')}</summary><p lang="es">${e(item.text)}</p></details>`;}

 function render(scroll=true){
  document.documentElement.lang=lang;document.title=`${t('title')} · Gernika-Lumo`;
  const parts=location.hash.slice(1).split('/'),route=parts[0]||'inicio';
  document.querySelector('nav').innerHTML=navItems.map(([id,es,eu])=>`<a href="#${id}" aria-current="${route===id?'page':'false'}">${dual(es,eu)}</a>`).join('');
  document.querySelector('#foot-local').textContent=t('local');document.querySelector('#foot-date').textContent=t('date');
  document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));
  if(route==='emakunde')main.innerHTML=renderEmakunde(parts[1],parts[2]);else if(route==='variable')main.innerHTML=renderVariable(parts[1],parts[2]);else if(route==='variables')main.innerHTML=renderCards(parts[1]);else if(route==='expediente')main.innerHTML=renderAnalysis(parts[1]);else if(route==='analisis')main.innerHTML=renderAnalyses();else if(route==='documentacion')main.innerHTML=renderDocs();else if(route==='metodologia')main.innerHTML=renderMethod()+renderPlanReview()+renderProvenance();else if(route==='resumen')main.innerHTML=renderSummary();else main.innerHTML=renderIntro();
  const pdfSelect=document.querySelector('#pdf-page');if(pdfSelect)pdfSelect.addEventListener('change',()=>{location.hash='emakunde/'+pdfSelect.value;});
  if(scroll){window.scrollTo(0,0);main.focus({preventScroll:true});if(parts[2])document.getElementById('indicator-'+parts[2])?.scrollIntoView({block:'start'});}
 }
 document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{lang=b.dataset.lang;try{localStorage.setItem('gernika-quality-language',lang);}catch{}render(false);}));
 window.addEventListener('hashchange',()=>render());render(false);
})();
